#!/bin/sh
hash=$(cat "$0" patches/*.patch | git hash-object --stdin) && echo $hash | cmp -s - build/hash || { r=https://ghcr.io/v2/exactly/maestro && t=$(curl -fsSm 10 'https://ghcr.io/token?scope=repository:exactly/maestro:pull') && a="Authorization: Bearer $(node -p 'JSON.parse(process.argv[1]).token' "$t")" && m=$(curl -fsSm 10 -H "$a" -H 'Accept: application/vnd.oci.image.manifest.v1+json' $r/manifests/$hash) && rm -rf build && mkdir build && curl -fsSL --connect-timeout 10 -Y 1000000 -y 10 -H "$a" $r/blobs/$(node -p 'JSON.parse(process.argv[1]).layers[0].digest' "$m") | tar -xzf - -C build && echo $hash > build/hash; } || { tmp=$(mktemp -d) && trap 'rm -rf $tmp' EXIT && src=$tmp/Maestro && git init -q $src && git -C $src fetch -q --depth 1 https://github.com/mobile-dev-inc/Maestro cli-2.12.1 && git -C $src checkout -q FETCH_HEAD && git -C $src apply $PWD/patches/*.patch && sdk=${ANDROID_HOME:-${ANDROID_SDK_ROOT:-$HOME/Library/Android/sdk}} && { [ ! -x $sdk/cmdline-tools/latest/bin/sdkmanager ] || { yes | $sdk/cmdline-tools/latest/bin/sdkmanager "platforms;android-$(sed -n 's/^ *compileSdk = //p' $src/maestro-android/build.gradle.kts).0" > /dev/null && ANDROID_HOME=$sdk $src/gradlew -p $src :maestro-android:assembleDebug :maestro-android:assembleAndroidTest && o=$src/maestro-android/build/outputs/apk && cp $o/debug/maestro-android-debug.apk $src/maestro-client/src/main/resources/maestro-app.apk && cp $o/androidTest/debug/maestro-android-debug-androidTest.apk $src/maestro-client/src/main/resources/maestro-server.apk; }; } && { x= && xcodebuild -version > /dev/null 2>&1 || x="-x :maestro-ios-driver:buildIosDriver"; } && $src/gradlew -p $src :maestro-cli:installDist $x && rm -rf build && mv $src/maestro-cli/build/install/maestro build && echo $hash > build/hash; }
